import React from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useEffect, useState } from 'react';
import axios from 'axios';

const ActivitiesPage: React.FC = () => {
  const { user } = useAuth();



  const getActivityIcon = (type: string) => {
    switch (type) {
      case 'entry': return '📥';
      case 'exit': return '📤';
      case 'alert': return '⚠️';
      case 'user': return '👤';
      case 'slot': return '🚗';
      case 'update': return '🔄';
      case 'system': return '⚙️';
      case 'security': return '🔒';
      default: return '📝';
    }
  };

  const getActivityColor = (type: string) => {
    switch (type) {
      case 'entry': return '#10b981';
      case 'exit': return '#3b82f6';
      case 'alert': return '#ef4444';
      case 'user': return '#9d4edd';
      case 'slot': return '#f59e0b';
      case 'update': return '#4ecdc4';
      case 'system': return '#8892b0';
      case 'security': return '#ff6b9d';
      default: return '#8892b0';
    }
  };

  return (
    <div className="container" style={{ padding: '40px 20px' }}>
      {/* Header */}
      <div style={{ marginBottom: '40px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <div>
            <h1 style={{ fontSize: '36px', marginBottom: '10px' }}>All Activities</h1>
            <p style={{ color: '#8892b0', fontSize: '16px' }}>
              Complete log of all system activities and user actions
            </p>
          </div>
          <Link to="/dashboard" className="btn btn-secondary">
            ← Back to Dashboard
          </Link>
        </div>

        {/* Filters */}
        <div style={{ display: 'flex', gap: '15px', flexWrap: 'wrap', marginBottom: '20px' }}>
          <button className="btn btn-primary" style={{ padding: '8px 16px' }}>
            All Activities
          </button>
          <button className="btn btn-secondary" style={{ padding: '8px 16px' }}>
            Entries Only
          </button>
          <button className="btn btn-secondary" style={{ padding: '8px 16px' }}>
            Exits Only
          </button>
          <button className="btn btn-secondary" style={{ padding: '8px 16px' }}>
            Alerts Only
          </button>
          <div style={{ flex: 1, minWidth: '200px' }}>
            <input
              type="text"
              placeholder="Search activities..."
              style={{
                width: '100%',
                padding: '10px 16px',
                background: 'rgba(17, 34, 64, 0.5)',
                border: '1px solid rgba(100, 255, 218, 0.2)',
                borderRadius: '8px',
                color: '#e6f1ff',
                fontSize: '14px',
              }}
            />
          </div>
        </div>
      </div>

      {/* Activities Table */}
      <div className="card">
        <div style={{ overflowX: 'auto' }}>
          <table className="data-table">
            <thead>
              <tr>
                <th>Activity</th>
                <th>User</th>
                <th>Zone</th>
                <th>Type</th>
                <th>Time</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {allActivities.map((activity) => (
                <tr key={activity.id}>
                  <td>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                      <div style={{
                        width: '40px',
                        height: '40px',
                        borderRadius: '10px',
                        background: `${getActivityColor(activity.type)}20`,
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        fontSize: '18px',
                        color: getActivityColor(activity.type),
                      }}>
                        {getActivityIcon(activity.type)}
                      </div>
                      <div>
                        <div style={{ color: '#e6f1ff', fontWeight: '500' as const }}>
                          {activity.action}
                        </div>
                      </div>
                    </div>
                  </td>
                  <td>
                    <div style={{ color: '#e6f1ff', fontWeight: '500' as const }}>
                      {activity.user}
                    </div>
                  </td>
                  <td>
                    <span style={{
                      padding: '4px 12px',
                      background: 'rgba(100, 255, 218, 0.1)',
                      border: '1px solid rgba(100, 255, 218, 0.3)',
                      borderRadius: '12px',
                      color: '#64ffda',
                      fontSize: '12px',
                      fontWeight: '600' as const,
                    }}>
                      {activity.zone}
                    </span>
                  </td>
                  <td>
                    <span style={{
                      padding: '4px 12px',
                      background: `${getActivityColor(activity.type)}20`,
                      border: `1px solid ${getActivityColor(activity.type)}`,
                      borderRadius: '12px',
                      color: getActivityColor(activity.type),
                      fontSize: '12px',
                      fontWeight: '600' as const,
                      textTransform: 'capitalize' as const,
                    }}>
                      {activity.type}
                    </span>
                  </td>
                  <td style={{ color: '#8892b0' }}>{activity.time}</td>
                  <td>
                    <button className="btn btn-secondary" style={{ padding: '6px 12px', fontSize: '12px' }}>
                      View Details
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div style={{ 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center',
          marginTop: '30px',
          paddingTop: '20px',
          borderTop: '1px solid rgba(100, 255, 218, 0.1)',
        }}>
          <div style={{ color: '#8892b0', fontSize: '14px' }}>
            Showing 12 of 150 activities
          </div>
          <div style={{ display: 'flex', gap: '10px' }}>
            <button className="btn btn-secondary" style={{ padding: '8px 16px' }}>
              Previous
            </button>
            <button className="btn btn-secondary" style={{ padding: '8px 16px' }}>
              Next
            </button>
          </div>
        </div>
      </div>

      {/* Summary Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginTop: '40px' }}>
        <div className="card">
          <div style={{ fontSize: '14px', color: '#8892b0', marginBottom: '8px' }}>Today's Activities</div>
          <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#64ffda' }}>48</div>
          <div style={{ fontSize: '12px', color: '#10b981', marginTop: '8px' }}>+12% from yesterday</div>
        </div>
        <div className="card">
          <div style={{ fontSize: '14px', color: '#8892b0', marginBottom: '8px' }}>Parking Entries</div>
          <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#10b981' }}>156</div>
          <div style={{ fontSize: '12px', color: '#10b981', marginTop: '8px' }}>Most active: Zone D</div>
        </div>
        <div className="card">
          <div style={{ fontSize: '14px', color: '#8892b0', marginBottom: '8px' }}>System Alerts</div>
          <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#ef4444' }}>3</div>
          <div style={{ fontSize: '12px', color: '#ef4444', marginTop: '8px' }}>Requires attention</div>
        </div>
        <div className="card">
          <div style={{ fontSize: '14px', color: '#8892b0', marginBottom: '8px' }}>User Registrations</div>
          <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#9d4edd' }}>5</div>
          <div style={{ fontSize: '12px', color: '#9d4edd', marginTop: '8px' }}>All verified</div>
        </div>
      </div>
    </div>
  );
};

export default ActivitiesPage;
